const express = require('express');
const app = express();
app.use(express.json());

let zadania = [];
let nastepneId = 1;

app.get('/api/zadania', (req, res) => {
    res.json(zadania);
});

app.post('/api/zadania', (req, res) => {
    const tytul = (req.body.tytul || '').trim();
    if (!tytul) return res.status(400).json({ blad: 'Tytuł jest wymagany' });
    const zadanie = { id: nastepneId++, tytul, zrobione: false };
    zadania.push(zadanie);
    res.status(201).json(zadanie);
});

app.put('/api/zadania/:id', (req, res) => {
    const zadanie = zadania.find((z) => z.id === Number(req.params.id));
    if (!zadanie) return res.status(404).json({ blad: 'Nie znaleziono' });
    if (req.body.tytul !== undefined) zadanie.tytul = req.body.tytul;
    if (req.body.zrobione !== undefined) zadanie.zrobione = Boolean(req.body.zrobione);
    res.json(zadanie);
});

app.delete('/api/zadania/:id', (req, res) => {
    const i = zadania.findIndex((z) => z.id === Number(req.params.id));
    if (i === -1) return res.status(404).json({ blad: 'Nie znaleziono' });
    zadania.splice(i, 1);
    res.sendStatus(204);
});

app.listen(3000);
